N = 321
R = [('comp_stats_save', 'Comp_Stats::save', '0x4ac4e0', 'comp_screens.cpp', 'thiscall', 'grava no temporário da competição, em ordem: a tabela de clubes (capacidade, contagem, entradas de 0x76), a de jogadores (entradas de 0x2d), o bloco +0x56a, os dois conjuntos de recordes, as chaves do arquivo, a contagem de fins de temporada, as bandeiras de recorde e as sequências guardadas (liberadas antes quando a contagem é 0); gravação curta para o jogo', "writes into the competition's temporary file, in order: the club table (capacity, count, 0x76-byte entries), the player table (0x2d-byte entries), the block +0x56a, both record sets, the archive keys, the season end count, the record flags and the saved runs (freed first when the count is 0); a short write stops the game"), ('comp_stats_load', 'Comp_Stats::load', '0x4ab890', 'comp_screens.cpp', 'thiscall', 'lê do temporário da competição na ordem da gravação: tabelas novas de clubes e de jogadores (nos dados antes da versão 0x3e015, entradas de jogador de 0x1d bytes com o resto zerado), o bloco +0x56a (só depois da versão 0x3e007), os recordes, as chaves, as bandeiras e as sequências guardadas; leitura curta para o jogo', "reads the competition's temporary file in the order it was written: new club and player tables (in data before version 0x3e015, player entries of 0x1d bytes with the rest zeroed), the block +0x56a (only after version 0x3e007), the records, the keys, the flags and the saved runs; a short read stops the game"), ('club_history_constructor', 'Club_History::Club_History', '0x442ab0', 'club_history.cpp', 'thiscall, ret 4', 'procura o CD (a caixa "Insert CD" até achar; o exe sem CD remenda a busca e a cópia lê os bytes), cria as listas em arquivo do histórico de liga (CM3_TEMP\\club league history.tmp, registros de 21 bytes) e de copa (club cup history.tmp, 11 bytes); com save, carrega os registros; senão um registro de 16 bytes por clube com os quatro deslocamentos em -1', 'searches the CD (the "Insert CD" box until found; a no-CD exe patches the search and the copy reads the bytes), creates the league history file list (CM3_TEMP\\club league history.tmp, 21-byte records) and the cup one (club cup history.tmp, 11 bytes); with a save, loads the records; otherwise one 16-byte record per club with the four offsets at -1'), ('club_history_destructor', 'Club_History::~Club_History', '0x442e20', 'club_history.cpp', 'thiscall', 'destrói as duas listas em arquivo e libera os registros dos clubes, zerando ponteiros e contagem', 'destroys both file lists and frees the club records, zeroing the pointers and the count'), ('club_history_load', 'Club_History::load', '0x443cd0', 'club_history.cpp', 'thiscall, ret 4', 'lê do item "club history.dat" do save a contagem e os registros de 16 bytes de cada clube; leitura curta ou falta de memória param o jogo', 'reads from the save\'s "club history.dat" item the count and each club\'s 16-byte records; a short read or no memory stops the game')]
