leia(N, 'as estatísticas das competições no save: a gravação; as estatísticas das competições no save: a carga; o histórico dos clubes: montar, destruir e carregar do save', 'the competition statistics in the save: writing them; the competition statistics in the save: reading them; the club history: building, destroying and loading from the save', [(a, e, f + ', ' + c, dp, de) for a, _, e, f, c, dp, de in R], tot, ac, lac_pt, lac_en,
     campos=[('Club_History +0 lista em arquivo do histórico de liga (FILE_LLIST, registros de 0x15), +4 a de copa (0xb), +8 registros por clube (0x10: +0/+4 primeiro e último deslocamento das temporadas de liga, +8/+0xc das campanhas de copa, -1 nenhum), +0xc a contagem; ponteiro e valor; grava (club_history_constructor, club_history_load) e libera (club_history_destructor)', 'Club_History +0 league history file list (FILE_LLIST, 0x15-byte records), +4 the cup one (0xb), +8 per-club records (0x10: +0/+4 first and last offsets of the league seasons, +8/+0xc of the cup runs, -1 none), +0xc the count; pointer and value; writes (club_history_constructor, club_history_load) and frees (club_history_destructor)')], interessa=['SGE', 'CMRTE'])
